def match(text, pat):
    """用 Z 函数找出 pat 在 text 中所有出现的起始下标(返回升序列表)。
    拼接 s = pat + 分隔符 + text,对 s 求 z;text 区段中 z[i] >= len(pat)
    即一次完整匹配。分隔符 chr(1) 须不在 pat/text 中出现。O(n+m)。"""
    m = len(pat)
    if m == 0:
        return list(range(len(text) + 1))
    s = pat + chr(1) + text
    z = z_array(s)
    res = []
    base = m + 1                    # text 在拼接串中的起始偏移(pat + 1 个分隔符)
    for i in range(base, len(s)):
        if z[i] >= m:               # 分隔符保证 z[i] 不超过 m
            res.append(i - base)
    return res

