def repeated_substring_pattern(s):
    """判断 s 是否由某个子串重复多次拼成(LC 459)。
    若存在周期 p:0 < p < n 且 p | n 且 z[p] == n - p
    (后缀 s[p:] 与前缀 s[:n-p] 完全重合),则 s 由 n/p 个长度 p 的块拼成。"""
    n = len(s)
    if n < 2:
        return False
    z = z_array(s)
    for p in range(1, n):
        if n % p == 0 and z[p] == n - p:
            return True
    return False
